      firebaseSdkVersion: backdrop.querySelector('#rpcm-ai-firebase-sdk')?.value || saved.firebaseSdkVersion,
      firebaseAppCheckDebugToken: typedAppCheck || saved.firebaseAppCheckDebugToken,
      vertexServiceAccount: typedVertex || saved.vertexServiceAccount,
      vertexLocation: backdrop.querySelector('#rpcm-ai-vertex-location')?.value || saved.vertexLocation,
      deepSeekApiKey: deepSeekKey,
      deepSeekBaseUrl: formBase,
      deepSeekModel: backdrop.querySelector('#rpcm-ai-deepseek-model')?.value || saved.deepSeekModel,
      deepSeekCustomModel: backdrop.querySelector('#rpcm-ai-deepseek-custom')?.value || '',
      deepSeekThinking: backdrop.querySelector('#rpcm-ai-deepseek-thinking')?.value !== '0',
      anthropicApiKey: typedAnthropic || saved.anthropicApiKey,
      anthropicModel: backdrop.querySelector('#rpcm-ai-anthropic-model')?.value || saved.anthropicModel,
      chatGptModel: backdrop.querySelector('#rpcm-ai-chatgpt-model')?.value ?? saved.chatGptModel,
      chatGptAccount: backdrop.querySelector('#rpcm-ai-chatgpt-account')?.value ?? saved.chatGptAccount,
      openAiApiKey: typedOpenAi || saved.openAiApiKey,
      openAiModel: backdrop.querySelector('#rpcm-ai-openai-model')?.value || saved.openAiModel,
      openAiReasoningEffort: backdrop.querySelector('#rpcm-ai-openai-reasoning')?.value || saved.openAiReasoningEffort,
      maxMessages: Number(backdrop.querySelector('#rpcm-ai-max-messages')?.value || saved.maxMessages),
      temperature: Number(backdrop.querySelector('#rpcm-ai-temperature')?.value || saved.temperature),
      maxOutputTokens: saved.maxOutputTokens,
      autoMemoryEnabled:saved.autoMemoryEnabled,
