  // Why a held queue cannot move yet (보류 대기열): one table for the held summary and the queue sheet.
  const HELD_QUEUE_WHY=Object.freeze({'live-full':'기존 보류를 정리하면 옮길 수 있습니다','adds-too-large':'이번 결과만으로 장부 용량을 넘습니다. 필요 없는 제안을 제외하거나 내보내 주세요','combined':'일부를 정리한 뒤 옮기기를 누르세요'});
  function wishCompactReadOnly(room,packs,references,rp,readOnlyPacks,budget=60000){
    if(JSON.stringify(readOnlyPacks).length<=budget)return 0;
    const norm=v=>String(v??'').normalize('NFC').replace(/\s+/gu,' ').trim().toLowerCase();
    const text=norm([rp.memory,rp.observe,rp.shared].filter(Boolean).join('\n')),ids=new Set(references.map(r=>r.id));
    const candidates=[];let index=0,changed=0;
    for(const pack of packs){
      const entries=(pack.entries||[]).filter(e=>!ids.has(e.id));if(!entries.length)continue;
      const view=readOnlyPacks[index++],active=(room.activeLorePackIds||[]).includes(pack.scopeId);
      entries.forEach((entry,i)=>{
        const row=view.entries[i];if(!active)row.packActive=false;if(entry.enabled===false)row.enabled=false;
        const relevant=[entry.name,...(entry.entities||[]),...(entry.triggers||[])].some(word=>{const k=norm(word);return k.length>=2&&text.includes(k);});
        if(entry.speechRule||relevant||(entry.anchor&&active))return;
        row.content=loreTextAtLevel(entry,'micro');row.level='micro';changed++;candidates.push({row,active});
      });
    }
    let size=JSON.stringify(readOnlyPacks).length;
    for(const {row} of candidates.sort((a,b)=>Number(a.active)-Number(b.active))){
      if(size<=budget)break;const before=JSON.stringify(row).length;row.content='';row.level='index';size+=JSON.stringify(row).length-before;
    }
    return changed;
  }
  // 자료 카드 in the 함께 정리 request, as the events are sent: related bodies and a title index (H4). U3.request calls it only when
  // the cards squeeze the events. Within the budget every card goes in full (null). Past it: the cards the new RP names (title, alias
  // or keyword of two characters or more) first, then the newest others, while the budget lasts; the rest go as ref·type·title rows,
  // newest first, while the index budget lasts. unsent: the cards the request has no body for.
  function wishSelectReferences(refs,rows,budget,indexBudget){
    if(JSON.stringify(refs||[]).length<=budget)return null;
    const norm=v=>String(v??'').normalize('NFKC').toLowerCase().replace(/\s+/g,' ').trim();
    const text=norm((rows||[]).map(t=>(t.userText||'')+'\n'+(t.assistantText||'')).join('\n'));
    const named=r=>[r.title,...(r.aliases||[]),...(r.keywords||[])].some(word=>{const k=norm(word);return k.length>=2&&text.includes(k);});
    const newest=[...refs].reverse(),order=[...newest.filter(named),...newest.filter(r=>!named(r))],sent=new Set();let chars=2;
    for(const r of order){const n=JSON.stringify({...r,ref:r.id,id:undefined}).length+1;if(chars+n<=budget){sent.add(r.id);chars+=n;}}
    const index=[];let indexChars=2;
    for(const r of newest){if(sent.has(r.id))continue;const row={ref:r.id,type:r.type,title:r.title},n=JSON.stringify(row).length+1;if(indexChars+n<=indexBudget){index.push(row);indexChars+=n;}}
    return {bodies:refs.filter(r=>sent.has(r.id)),index,unsent:refs.filter(r=>!sent.has(r.id)).map(r=>r.id)};
  }
  // An answer's references.upsert rows for cards its request sent without a body (req.referenceUnsent) are left out, before any
  // format check: the AI never read those cards. The rest of the answer goes on; the input object is not changed.
  function wishDropUnsentReferenceRows(data,req){
    const unsent=new Set(req?.referenceUnsent||[]),rows=data?.memory?.references?.upsert;
    if(!unsent.size||!Array.isArray(rows))return data;
    return {...data,memory:{...data.memory,references:{...data.memory.references,upsert:rows.filter(row=>!unsent.has(String(row?.ref??'').trim()))}}};
  }
  function wishRequestSizeInfo(guide,schema,data){
    const chars=value=>JSON.stringify(value??null).length;
    return {guide:String(guide||'').length+chars(schema),rp:chars(data.rp),events:chars(data.memory?.events),state:chars(data.memory?.state),references:chars(data.memory?.references)+(data.memory?.reference_index?chars(data.memory.reference_index):0),threads:chars(data.memory?.threads)+chars(data.memory?.thread_closed_index),timeline:chars(data.memory?.timeline),readOnlyPacks:chars(data.readOnlyPacks),fixed:chars(data.fixed),observe:chars(data.observe)};
  }
  function wishRequestSizeMessage(s){
    const n=k=>Number(s?.[k]||0).toLocaleString();
    const text='구성: 지침+스키마 '+n('guide')+' · RP '+n('rp')+' · 사건 '+n('events')+' · 현재상태 '+n('state')+' · 자료 카드 '+n('references')+' · 서사 고리 '+n('threads')+' · 자료집 참고 '+n('readOnlyPacks')+' · 고정 설정 '+n('fixed')+' · 인물/인지 '+n('observe');
    return text+(s?.readOnlyPacks>0&&s.readOnlyPacks>=Math.max(s.guide,s.rp,s.events,s.fixed,s.observe,Number(s.state||0),Number(s.references||0),Number(s.threads||0),Number(s.timeline||0))?' · 자료집 참고가 가장 큽니다. 큰 자료를 정리하거나 사용 중인 다른 자료팩의 포함 상태를 조정해 주세요.':'');
  }

  // These operations run synchronously inside the owning store's existing guarded write.
  function wishHeldRecord(domain,record){
    if(domain==='A')return {live:record.relationshipHeld||[],resolved:record.relationshipHeldResolved||[]};
    if(domain==='C')return {live:(record.reviews||[]).filter(r=>WishHeld.isHeld('C',r)),resolved:record.heldResolved||[]};
    if(domain==='F')return {live:record.loreAutomation?.apiHeldProtected||[],resolved:record.loreAutomation?.apiHeldResolved||[]};
    throw Error('알 수 없는 보류 제안 종류입니다.');
  }
  function wishHeldWrite(domain,record,ledger,resolved){
    if(domain==='A'){record.relationshipHeld=ledger;record.relationshipHeldResolved=resolved;}
    else if(domain==='C'){record.reviews=[...(record.reviews||[]).filter(r=>!WishHeld.isHeld('C',r)),...ledger];record.heldResolved=resolved;}
    else if(domain==='F'){record.loreAutomation||={};record.loreAutomation.apiHeldProtected=ledger;record.loreAutomation.apiHeldResolved=resolved;}
    else throw Error('알 수 없는 보류 제안 종류입니다.');
  }
  function wishHeldRecordChange(domain,record,records,action,jobCreatedAt){
    const {live,resolved}=wishHeldRecord(domain,record);
    if(action==='move'){
      const p=WishHeld.partition(domain,live,records,resolved,[],domain==='A'?{rows:record.relationships||[]}:{});
      wishHeldWrite(domain,record,p.ledger,WishHeld.resolve(resolved,p.settled,'auto-matched',Date.now()));
      const remaining=new Set(p.queued.map(r=>r.id)),done=records.filter(r=>!remaining.has(r.id));
      return {moved:Math.max(0,p.ledger.length-live.length+p.settled.filter(r=>live.includes(r)).length),remaining:p.queued.length,suppressed:p.suppressed.length,done};
    }
    if(!['dismiss','dismiss-id'].includes(action))throw Error('알 수 없는 보류 처리입니다.');
    const ledger=live.filter(r=>!records.some(x=>(action!=='dismiss-id'||r.id===x.id)&&WishHeld.same(domain,r,x)));
    wishHeldWrite(domain,record,ledger,WishHeld.resolve(resolved,records,'dismissed',Date.now(),jobCreatedAt));
    return {done:records,moved:0,remaining:0,suppressed:0};
  }
  function wishHeldJobCount(j){return (j?.draft?.relationshipHeldAdds?.length||0)+(j?.draft?.cognitionHeldAdds?.length||0)+(j?.draft?.heldProtected?.length||0);}
  function wishHeldJobSuffix(j){const n=wishHeldJobCount(j);return n?' (미적용 보류 제안 '+n+'건 포함)':'';}
  function wishHeldPauseMessage(n){return '이번 작업에서 보류 제안이 '+n+'건 생겼습니다. 방금 구간 결과는 저장했습니다. 이어서 실행하면 다음 구간부터 이어집니다. 그 전에 기억·인물·자료를 고치면 작업 기준이 바뀌어 대화를 다시 읽어야 합니다';}
  // A 검토 item about automatic facts (auto-fact-*) has nothing left to do once one of its facts is gone or archived: a
  // rebuild drops every automatic fact, and the user may delete or end tracking of one. A commit takes it off as dismissed.
  function wishHeldFactGone(rec,cog){
    if(!/^auto-fact-/.test(String(rec?.reason||'')))return false;
    const p=rec.payload||{};
    return [p.fact_id,p.target_fact_id,p.new_fact_id].filter(Boolean).some(id=>!(cog?.facts||[]).some(f=>f.id===id&&!f.archived));
  }
  function wishHeldCommitNotice(staged,parts){
    const queued=parts.reduce((n,p)=>n+p.queued.length,0),suppressed=parts.flatMap(p=>p.suppressed),settled=parts.reduce((n,p)=>n+p.settled.length,0),duplicate=parts.reduce((n,p)=>n+p.duplicate.length,0);
    const total=(staged.relationshipHeldAdds?.length||0)+(staged.cognitionHeldAdds?.length||0),notices=staged.notices||=[];
    const text=[queued?'보류 제안 '+total+'건 중 '+queued+'건은 장부 용량 초과로 대기열에 보관':'',suppressed.length?'이미 확인한 같은 제안 '+suppressed.length+'건은 다시 추가하지 않음':''].filter(Boolean).join(' · ');if(text)notices.push(text);
    if(settled)notices.push('보류 제안 '+settled+'건이 결과와 일치해 정리됨');
    if(total||settled)try{WLOG.fail('held-commit',text||'보류 제안 저장 완료',{level:queued?'warn':'info',added:Math.max(0,total-queued-suppressed.length-duplicate),queued,duplicate,suppressed:suppressed.length,settled,suppressedSigs:suppressed.map(r=>r.sig)});}catch{}
  }

// Rows of one key an AI answer or file wrote more than once: the same row again counts once; rows that differ are all left out (which
// one holds is not guessed) and skip(error) names the key once. A row whose key cannot be read is kept for its own checks.
function wishOnceRows(rows,keyOf,message,skip){
  const by=new Map(),list=Array.isArray(rows)?rows:[];
  for(const row of list){let k='';try{k=String(keyOf(row)??'');}catch{continue;}if(!k)continue;if(!by.has(k))by.set(k,[]);by.get(k).push(row);}
  const drop=new Set();
  for(const [k,same] of by){if(same.length<2)continue;const one=same.every(x=>JSON.stringify(x)===JSON.stringify(same[0]));for(const x of one?same.slice(1):same)drop.add(x);if(!one)skip(Error(message(k,same[0])));}
  return drop.size?list.filter(row=>!drop.has(row)):list;
}
