      const query=normal(rows.map(t=>(t.userText||'')+'\n'+(t.assistantText||'')).join('\n'));
      const names=new Set((db.people||[]).flatMap(p=>[p.name,...(p.aliases||[])]).map(normal));
      const aliasGroups=[...(db.people||[]).map(p=>[p.name,...(p.aliases||[])]),...(db.references||[]).map(r=>[r.title,...(r.aliases||[]),...(r.keywords||[])])].map(xs=>xs.map(normal).filter(x=>x.length>=2));
