  async function roomCopyPreview(id){
    const d=WUI.ui.dlg(id);if(!d?.inventory||d.busy)return;roomCopyAssertTarget(d);d.busy=true;d.error='';WUI.paint();
    try{
      if(unstartedRooms.has(d.targetRoom))await saveRoom(d.targetRoom);
      await storageWrites.get(d.targetId);
      const [targetRaw,targetCg]=await Promise.all([getStoredRoomRecord(d.targetId),getStoredCognitionRecord(apiChatIdOf(d.targetRoom))]);roomCopyAssertTarget(d);if(!targetRaw)throw Error('현재 방 저장 자료를 읽지 못했습니다.');if(roomCopyLiveStamp(targetRaw)!==roomCopyLiveStamp(d.targetRoom))throw Error('아직 저장되지 않은 현재 방 변경이 있습니다. 저장을 마친 뒤 적용 확인을 다시 눌러 주세요.');
      const plan=roomCopyBuildPlan(d,d.draft,targetRaw,targetCg),source=d.sourceRaw,sourceCg=d.sourceCogRaw||{},heldSc=await WishHeld.readSidecar(source);
      const heldN=(source.relationshipHeld||[]).length+(sourceCg.reviews||[]).filter(x=>WishHeld.isHeld('C',x)).length+(source.loreAutomation?.apiHeldProtected||[]).length,queuedN=['A','C','F'].reduce((n,k)=>n+heldSc.queue[k].length,0);
      if(heldN||queuedN)plan.warnings.push('보류 '+heldN+'건·대기 '+queuedN+'건은 원본 방에 남습니다');
      roomCopyAssertTarget(d);d.preview={plan,targetRaw,targetCg,targetLive:roomCopyLiveStamp(d.targetRoom)};d.draft.stage='review';
    }catch(e){d.error=WLOG.inline("방 복사 미리보기",e);}finally{d.busy=false;WUI.paint();}
  }
  async function roomCopyCommitLocal(session,preview){
    const {plan,targetRaw,targetCg}=preview,targetRoom=session.targetRoom;
    return new Promise((resolve,reject)=>{
      const tx=state.db.transaction([APP.storeName,APP.cognitionStoreName,APP.libraryStoreName,APP.runtimeStoreName],'readwrite'),rooms=tx.objectStore(APP.storeName),cogs=tx.objectStore(APP.cognitionStoreName),libs=tx.objectStore(APP.libraryStoreName),runtime=tx.objectStore(APP.runtimeStoreName);let issue,left=2+Object.keys(plan.lore.checks).length;
      const fail=message=>{if(issue)return;issue=Error(message);try{tx.abort();}catch{}};
      const done=()=>{if(--left||issue)return;
        try{roomCopyAssertTarget(session);if(roomCopyLiveStamp(targetRoom)!==preview.targetLive||targetRoom.pending||generationPending(apiChatIdOf(targetRoom)))return fail('적용 직전에 현재 방 또는 주입 상태가 바뀌었습니다. 다시 확인해 주세요.');
          const recovery={id:'wish-copy-recovery:'+crypto.randomUUID(),kind:'wish-copy-recovery',chatId:session.targetId,at:Date.now(),room:structuredClone(targetRaw),cognition:structuredClone(targetCg),newPackIds:plan.lore.writes.map(p=>p.scopeId)};runtime.put(recovery);
          const q=runtime.getAll(IDBKeyRange.bound('wish-copy-recovery:','wish-copy-recovery:\uffff'));
          q.onsuccess=()=>{const old=(q.result||[]).filter(x=>x.kind==='wish-copy-recovery'&&x.chatId===recovery.chatId&&x.id!==recovery.id).sort((a,b)=>Number(b.at||0)-Number(a.at||0));for(const x of old.slice(2))runtime.delete(x.id);};
          plan.target._rev=Number(targetRaw._rev||0)+1;plan.target._epoch=targetRaw._epoch||crypto.randomUUID();plan.target.updatedAt=nowIso();rooms.put(plan.target);
          // What the copy adds to the cognition record is the user's own change: it leaves the mark a direct edit leaves (되감기 복원
          // then keeps the record's knowledge, types and concealments as they are now).
          if(plan.cog.changed){const cg=plan.cog.record;cg.rev=Number(targetCg?.rev||0)+1;cg.updated=Date.now();cg.events=[...(Array.isArray(cg.events)?cg.events:[]),{at:cg.updated,text:'사용자 직접 수정'}].slice(-100);cogs.put(cg);}
          for(const pack of plan.lore.writes)libs.put(pack);
        }catch(e){fail(e.message||String(e));}
      };
      const check=(store,key,expected,label,stamp=copyFullStamp)=>{const q=store.get(String(key));q.onsuccess=()=>{if(stamp(q.result||null)!==expected)return fail(label+'이(가) 미리보기 이후 변경되어 전체 복사를 취소했습니다.');done();};};
      check(rooms,targetRaw.chatId,copyFullStamp(targetRaw),'현재 방');
      check(cogs,apiChatIdOf(targetRaw),copyFullStamp(targetCg),'현재 인지');
      for(const [id,stamp] of Object.entries(plan.lore.checks))check(libs,id,stamp===null?'null':stamp,'자료집',lorePackStorageFingerprint);
      tx.oncomplete=()=>resolve(plan);tx.onabort=tx.onerror=()=>reject(issue||tx.error||WLOG.tag(Error('복사 저장 실패'),'STORE_TX_FAIL'));
    });
  }

  async function applyRoomDataCopy(id){
    const d=WUI.ui.dlg(id);if(!d?.preview||d.busy)return;roomCopyAssertTarget(d);
    if(d.targetRoom.pending||roomCopyBusy()||generationPending(apiChatIdOf(d.targetRoom)))throw Error('주입을 해제하고 생성·정리 작업이 끝난 뒤 복사해 주세요.');
    if(d.preview.plan.selectionStamp!==copyFullStamp({pick:d.draft.pick,stateMode:d.draft.stateMode,activate:d.draft.activate}))throw Error('선택 내용이 바뀌었습니다. 적용 확인을 다시 열어 주세요.');
    if(!confirm(`‘${roomCopyLabel(d.sourceRaw)}’에서 선택한 자료를 ‘${roomCopyLabel(d.targetRoom)}’에 복사할까요?\n\n${d.preview.plan.rows.length}항목 · 원본은 그대로 유지\n${d.draft.stateMode==='replace'&&d.preview.plan.rows.some(r=>r.category==='state')?'주의: 현재상태 전체를 원본 상태로 교체합니다.\n':''}자료집은 진행형 자료에 합치지 않고 별도 참고 팩으로 저장합니다.`))return;
    d.busy=true;d.error='';WUI.paint();
    try{
      const targetRid=String(apiChatIdOf(d.targetRoom)),keys=[targetRid,'ai:'+targetRid];
      await WLOG.show('복사 중…',()=>withRoomExclusiveKeys(keys,async()=>{
        roomCopyAssertTarget(d);if(roomCopyBusy()||d.targetRoom.pending||generationPending(targetRid))throw Error('잠금 대기 중 생성·주입 상태가 바뀌었습니다.');
        memoryImportRunning=true;
        try{
          const plan=await roomCopyCommitLocal(d,d.preview);Object.assign(d.targetRoom,plan.target);
          for(const pack of plan.lore.writes){const i=lorePackCache.findIndex(p=>p.scopeId===pack.scopeId);if(i<0)lorePackCache.push(pack);else lorePackCache[i]=pack;}state.v2LorePacks=lorePackCache;
          U3.invalidate(d.targetRoom);allFitRankCache.clear();recallScoreStoreClear();LORE_QUERY_VECTOR_CACHE.clear();
          if(plan.cog.changed){const b=cogBridge();try{await b?.invalidateRuntime?.(targetRid);await b?.refresh?.();state.v2Cognition=await b?.getView?.(targetRid);}catch{state.v2Cognition=null;}}
          d.completed=true;d.busy=false;WUI.closeSheet(d,true);renderModalIfOpen();notify(`선택 자료 복사 완료 · 자료집 ${plan.lore.writes.length}팩/${plan.lore.entries}카드 · 관계 ${plan.stats.relationships?.added||0}방향 · 서사 고리 ${plan.stats.threads?.added||0}개`,'success',5500);
        }finally{memoryImportRunning=false;}
      }));
    }catch(e){d.error=WLOG.inline(WLOG.dialogLabel(d),e);d.preview=null;d.draft.stage='choose';}finally{d.busy=false;WUI.paint();}
  }

