        const tx=state.db.transaction([APP.storeName,APP.cognitionStoreName,APP.libraryStoreName,APP.runtimeStoreName],'readwrite'),out={};let left=3,issue;
        const fail=e=>{issue=e;try{tx.abort();}catch(_){}};
