  function recallScoreBook(){let book=null;try{book=JSON.parse(localStorage.getItem(RECALL_SCORE_STORE_KEY)||'null');}catch(_){}return book&&typeof book==='object'&&!Array.isArray(book)?book:{};}
  function recallScoreRestore(entry,key){
    if(entry.restored)return;entry.restored=true;
    const saved=recallScoreBook()[key];if(!saved||!Array.isArray(saved.rows))return;
    for(const r of saved.rows)if(Array.isArray(r)&&typeof r[0]==='string'&&!entry.rows.has(r[0])&&Number.isInteger(r[1])&&r[1]>=0&&r[1]<=100&&(r[2]===0||r[2]===1)&&Number.isFinite(r[3]))entry.rows.set(r[0],{relevance:r[1],related:r[2]===1,local:r[3]});
  }
  function recallScoreSave(key,rows){
    if(allFitRankCache.get(key)?.rows!==rows)return;
    const book=recallScoreBook();book[key]={at:Date.now(),rows:[...rows].map(([k,s])=>[k,s.relevance,s.related?1:0,s.local])};
    try{localStorage.setItem(RECALL_SCORE_STORE_KEY,JSON.stringify(Object.fromEntries(Object.entries(book).filter(e=>e[1]&&Number.isFinite(e[1].at)&&Array.isArray(e[1].rows)).sort((a,b)=>b[1].at-a[1].at).slice(0,RECALL_SCORE_STORE_MAX))));}catch(_){}
  }
  function allFitLimit(room) {
    return Math.min(Number(room?.maxChars) || APP.defaultMaxChars, APP.carrierSafeChars);
  }
  function carrierFallbackLimit(room) {
    return Math.min(allFitLimit(room), APP.carrierFallbackChars);
  }
  function isServerPatch500(error) {
    const message=String(error?.message||error||'');
    return message.includes('메시지 PATCH 실패')&&/API 오류 500/.test(message);
  }
  // Message PATCH takes a JSON body of at most 102,400 bytes and answers 413 above it, in UTF-8 and in UTF-16LE alike
  // (measured 2026-10-05/06; contents v3 and crack-gen v3 store a BOM-less UTF-16LE body sent as 'application/json; charset=utf-16le' exactly).
  // Each body goes in the smaller of the two, so carrierByteBudget (1,000 bytes of slack) counts the bytes actually sent, escapes included.
  // UTF-16LE stays off for the rest of the page once the server refuses it, stores it differently or it cannot go out at all (sendCarrierPatch).
  // `answered`: a UTF-16LE PATCH got an HTTP answer (any status) on this page, so this userscript manager does send it.
  // `encoding` (optional) counts the body in that encoding instead: the panel shows a verified carrier in the one it was sent in.
  // A page starts with UTF-16LE off when GM_info.scriptHandler names a manager whose Blob body does not reach the server as
  // sent (Stay, Userscripts, AdGuard), or when this browser kept a refusal (localStorage: Userscripts has no GM storage) for the
  // same manager name and manager version less than 7 days ago (a WRMC update keeps it: the refusal is the manager's). A refusal is kept after a 4xx refusal is followed
  // by a UTF-8 PATCH that goes through (sendCarrierPatch); 5xx and unanswered requests are never kept.
