      const vector = entry?.embedding;if (!vector?.sourceHash || !Array.isArray(vector.vector) || !vector.vector.length) continue;
      const seen = newest.get(String(vector.sourceHash));if (!seen || Number(vector.updatedAt || 0) > Number(seen.updatedAt || 0)) newest.set(String(vector.sourceHash), vector);
