  function scheduleAutomaticLoreMaintenance(room,reason='scheduled',delay=900,force=false){if(force)return void U3.run(room,'memory');U3.schedule(room,delay);}

  function resolvedSpeechRelations(room) {
    const winners=new Map();
    (room?.loreConfig?.enabled===false?[]:activeLorePacks(room)).forEach((pack,packIndex)=>{
      (pack.entries||[]).forEach((entry,entryIndex)=>{
        if(entry?.enabled===false||!entry?.speechRule)return;
        const rule=normalizeLoreSpeechRule(entry.speechRule);
        const key=rule&&speechPairKey(rule.speaker,rule.target);if(!key)return;
        const candidate={
          id:`lore-speech:${pack.scopeId}:${entry.id}`,speaker:rule.speaker,target:rule.target,address:rule.address,
          register:rule.register,note:rule.note,effectiveTurnSeq:rule.effectiveTurnSeq,revision:rule.revision,
          source:'lore',sourcePackId:pack.scopeId,sourceEntryId:entry.id,_order:packIndex*100000+entryIndex,
        };
        const previous=winners.get(key);
        const newer=!previous
          ||candidate.effectiveTurnSeq>previous.effectiveTurnSeq
          ||(candidate.effectiveTurnSeq===previous.effectiveTurnSeq&&candidate.revision>previous.revision)
          ||(candidate.effectiveTurnSeq===previous.effectiveTurnSeq&&candidate.revision===previous.revision&&candidate._order>previous._order);
        if(newer)winners.set(key,candidate);
      });
    });
    // 방별 현재값은 자료집의 기본/과거 규칙보다 항상 우선합니다.
    for(const relation of normalizeSpeechRelations(room?.speechRelations||[]))winners.set(speechPairKey(relation.speaker,relation.target),{...relation,source:'room',_order:Number.MAX_SAFE_INTEGER});
    return [...winners.values()].map(({_order,...relation})=>relation).sort((a,b)=>a.speaker.localeCompare(b.speaker,'ko')||a.target.localeCompare(b.target,'ko'));
  }

  // The complete winners stay in storage/UI/analysis. Only their injection view follows the same three-turn window as relationships.
  function speechParticipantResolver(room){
    const cached=cogBridge()?.getActorsSync?.(apiChatIdOf(room)),view=state.v2Cognition;
    const actors=Array.isArray(cached)?cached:String(view?.id||'')===String(apiChatIdOf(room))&&Array.isArray(view?.actors)?view.actors:null;
    const identities=new Map(),names=new Map();
    const add=(id,name,aliases,pc)=>{
      if(!name)return;const key=id?'actor:'+id:'name:'+speechNameKey(name),old=identities.get(key);
      if(old){old.aliases=[...new Set([...old.aliases,name,...aliases])];old.isPlayer=old.isPlayer&&!!pc;return;}
      identities.set(key,{key,name,aliases:[...new Set([name,...aliases])],isPlayer:!!pc});
    };
    if(actors)for(const a of actors){if(!a.archived)add(String(a.id||''),String(a.name||''),a.aliases||[],a.isPlayer);}
    else for(const r of room.relationships||[])for(const side of ['speaker','target'])add(r[side+'ActorId'],r[side],r[side+'Aliases']||[],r[side+'PC']);
    for(const x of identities.values())for(const name of x.aliases){const k=speechNameKey(name);if(k){if(!names.has(k))names.set(k,new Map());names.get(k).set(x.key,x);}}
    return name=>{const k=speechNameKey(name),hits=names.get(k);return hits?.size===1?[...hits.values()][0]:{key:'name:'+k,name:String(name||''),aliases:[String(name||'')],isPlayer:false};};
  }
  function speechForcedPairs(room,resolve){
    const out=new Set(),choices=room.pending?.quickIncludes||{};
    for(const r of room.relationships||[]){const choice=choices['slot:relationship:'+r.id];if(r.enabled===false||!(r.pinned||choice?.version===2&&choice.action==='include'))continue;out.add(JSON.stringify([resolve(r.speaker).key,resolve(r.target).key]));}
    return out;
  }
  function speechInjectionRows(room,rows=null){
    if(room?.speechConfig?.enabled===false)return [];
    rows=rows||resolvedSpeechRelations(room);
    const all=room.pending?.quickIncludes?.['slot:current-speech'];
    if(all?.version===2&&all.action==='include')return rows;
    const resolve=speechParticipantResolver(room),forced=speechForcedPairs(room,resolve),live=state.currentRoom;
    // A manual mutation projects a clone before committing it; use the same room's verified window, never another room's.
    const windowRoom=live&&live!==room&&String(live.chatId)===String(room.chatId)&&String(apiChatIdOf(live))===String(apiChatIdOf(room))&&live._epoch===room._epoch?live:room;
    const context=speechNameKey(WishRelationships.selectionText(windowRoom));
    return rows.filter(row=>{
      const from=resolve(row.speaker),to=resolve(row.target);
      if(forced.has(JSON.stringify([from.key,to.key])))return true;
      return WishRelationships.matchesIn({speaker:from.name,target:to.name,speakerAliases:from.aliases,targetAliases:to.aliases,speakerPC:from.isPlayer,targetPC:to.isPlayer},context);
    });
  }

  // keep (required fit): applied after the relevance filter; it can never re-add an off-window direction.
  function speechRelationsText(room, { includeRule = true, respectEnabled = true, noteTransform = null, keep = null } = {}) {
    if(respectEnabled&&room?.speechConfig?.enabled===false)return '';
    const eligible=speechInjectionRows(room),rows=keep?eligible.filter(keep):eligible;
    if(!rows.length)return '';
    const head=includeRule?'인물이 지금 상대를 부르는 호칭과 말투다. 예전 호칭으로 되돌리지 않는다.\n':'';
    return head+rows.map(row=>{const note=noteTransform?noteTransform(row):row.note;return `- ${row.speaker} → ${row.target}: ${row.address?'“'+row.address+'”'+(/[가-힣]$/.test(row.address)&&(row.address.charCodeAt(row.address.length-1)-0xAC00)%28?'이라고':'라고')+' 부름':'호칭 미확정'} · ${speechRegisterLabel(row.register)}${note?` · ${note}`:''}`;}).join('\n');
  }

  function currentSpeechPendingItem(room) {
    const content=speechRelationsText(room);
    if(!content)return null;
    return {slotId:'__speech',sourceSlotId:'__speech',sourceKey:'current-speech',title:'현재 호칭·말투 — 과거 규칙보다 우선',group:'speech',content,totalTurns:0,usedTurns:0,autoType:'current-speech',recallReason:'최근 3턴·이번 입력의 관련 방향 · 현재 호칭 우선'};
  }

  function replaceSpeechPendingItem(room) {
    if(!room?.pending)return 0;
    const before=(room.pending.items||[]).find(item=>item?.slotId==='__speech'||item?.group==='speech')?.content||'';
    room.pending.items=(Array.isArray(room.pending.items)?room.pending.items:[]).filter(item=>item?.slotId!=='__speech'&&item?.sourceSlotId!=='__speech'&&item?.group!=='speech');
    const item=currentSpeechPendingItem(room);
    if(before!==String(item?.content||''))room.pending.recallNeedsRefresh=true;
    if(item){item.turnStartUserId=String(room.pending.latestUserId||room.pending.turnStartUserId||'');room.pending.items.unshift(item);return 1;}
    return 0;
  }

  // 서사 고리 short list as one always-included item. Its identity never depends on the text, so a session exclusion keeps
