  async function syncLoreMutation(room, reason = 'lore-change') {
    scheduleSemanticIndex(room);
    if (!room?.pending) return '';
    try {
      await refreshHybridRecall(room,room.autoRecallContextText||'',{allowAi:false,allowSemanticNetwork:false});
      await syncPendingCarrier(room, reason);
      return '';
    } catch (error) {
      return String(error?.message || error || '현재 주입 갱신 실패');
    }
  }

