      if(!review){notify('검토 후보가 이미 바뀌었습니다. 화면을 다시 확인해 주세요.','warn',4200);state.v2Cognition=null;v2ScheduleAsyncRefresh(room);return;}
      const p=review.payload||{}, cog=state.v2Cognition||{};
