      if(rid!==currentChat()||sendRoute!==state.routeEpoch||sendRestore!==localRestoreEpoch||currentRoom!==state.currentRoom||(currentRoom&&String(apiChatIdOf(currentRoom))!==rid))throw new Error('방이 바뀌어 이전 전송을 중단했습니다.');
