  const WUI_BUTTON_ICONS={economyBackup:'down',api:'key',memoryBase:'clock',unifiedMemory:'refresh',unifiedAll:'spark',unifiedRetry:'refresh',cogRe:'refresh',rebuildRead:'book',rebuildRun:'spark',rebuildApply:'check',rebuildStop:'pause',rebuildClear:'trash',secondaryExport:'down',secondaryImport:'up',fileBackup:'down',fileRestore:'up',spDel:'trash',charDel:'trash',xDel:'trash',ftDel:'trash',thDel:'trash'};
  const WUI_AI_CALLS=new Set(['unifiedMemory','unifiedAll','unifiedRetry','cogRe','rebuildRun','nativeBundleRun','lcRun','loreConvert','loreApiBundle','aiTest','editRerun','loreLevels']);
