    return `<div class="m3-whysum"><span><b>${inCount}</b> ${V.inj.verified?'들어감':'주입 후보'}</span><span class="${out?'is-out':''}"><b>${out}</b> 빠짐</span></div>${bar}${chips}<div class="m3-irows">${list||empty('이 조건에 맞는 항목이 없습니다.')}</div>`;
