      add(auto ? '설명' : '변경 제안', v2ReviewDescription(r, cog), 'is-main');
      if (r.reason === 'auto-fact-rewrite') { add('옛 인지 본문', p.content); add('옛 인지를 아는 인물', who(q.fact_id)); add('새 인지 본문', body(q.new_fact_id)); add('새 인지를 아는 인물', who(q.new_fact_id)); }
