      for(let k=1;k<seg.length-1;k++){const s=seg[k];if(s.eq&&!seg[k-1].eq&&!seg[k+1].eq&&len(s.b)<=big(seg[k-1])&&len(s.b)<=big(seg[k+1])){const p=seg[k-1],q=seg[k+1];p.a+=s.a+q.a;p.b+=s.b+q.b;seg.splice(k,2);k=Math.max(0,k-3);}}
