      const e=mk('path',{class:'e '+(rel?'rel':'sp'),d:dd});e.style.setProperty('--len',Math.ceil(len*1.2));e.style.setProperty('--dl',(.25+Math.min(i,10)*.035)+'s');
      if(!rel)e.addEventListener('animationend',()=>e.classList.add('done'),{once:true});
