        g.append(mk('circle',{r:8.5}),mk('path',{d:'M-2.5 -.5v-2a2.5 2.5 0 0 1 5 0v2'}),mk('rect',{x:-3.6,y:-.8,width:7.2,height:5.2,rx:1.2}));
