    q('[data-f]').onclick=e=>{const b=e.target.closest('button');if(!b)return;d.draft.f=b.dataset.v;secretPair=null;q('[data-f]').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));paint(false);};
