    qi.onkeydown=e=>{if(e.key!=='Enter')return;const k=qi.value.trim().toLowerCase(),hit=nodes.find(n=>k&&String(n.name).toLowerCase().includes(k));if(hit){d.draft.sel=hit.id;secretPair=null;paint(true);}};
