// Shared prompt editor. Defaults are resolved lazily after all engines initialize.
const WishPromptGuides=(()=>{
  const catalog=[
    ['apiCommon','공통 추출 규칙','api'],['apiMemory','현재상태 · 날짜별 사건 · 자료','api'],['apiThreads','서사 고리 · 외부 AI와 공통','api'],['apiTimeline','연표 · 외부 AI와 공통','api'],
    ['apiObserve','인물 · 인지 · 은폐','api'],['apiSpeech','호칭 · 말투','api'],
    ['apiRelationships','관계 · 감정선','api'],['apiDate','날짜 · 시점 판정','api'],
    ['apiDelta','절약 모드 · 현재상태 변경분','api'],['apiRecall','AI 후보 선별','api'],
    ['apiBundleMemory','기억 묶음 정리 · 내장 API','api'],['apiBundlePeople','인물 묶음 정리 · 내장 API','api'],['apiIndex','절약 모드 · 후보 색인','api'],['apiLoreConversion','텍스트 → 자료 카드','api'],['apiLoreBundle','자료집 묶음 정리 · 내장 API','api'],
    /* PRIVATE_CATALOG */
    ['externalAll','외부 AI · 전체 재구축','external'],['externalMemory','외부 AI · 기억 재구축','external'],['apiThreads','외부 AI · 서사 고리 · API와 공통','external'],['apiTimeline','외부 AI · 연표 · API와 공통','external'],['externalPeople','외부 AI · 인물 재구축','external'],['externalRelationships','외부 AI · 관계 재구축','external'],
    ['externalSecondary','외부 AI · 2차 재구축','external'],['externalFreeCompression','외부 AI · 원문 자유 압축','external'],['loreExternal','외부 AI · 자료집 재구축','external'],['manualRelay','외부 AI · 복붙 공통 안내','external']
  ];
  const raw=id=>localStorage.getItem(API_GUIDE_STORAGE_KEYS[id]);
  function load(d,id){
    if(!catalog.some(row=>row[0]===id&&row[2]===d.group))throw Error('지원하지 않는 지침입니다.');
    if(!Object.hasOwn(d.edits,id)){d.before[id]=raw(id);d.edits[id]=getGuideText(id);d.initial[id]=d.edits[id];}
    else if(!Object.hasOwn(d.before,id)){d.before[id]=raw(id);d.initial[id]=getGuideText(id);}
    d.draft.selected=id;d.draft.text=d.edits[id];
  }
  function open(id='apiCommon'){
    id=({currentState:'apiMemory',logSummary:'apiMemory',loreAuto:'apiLoreBundle'})[id]||id;
    const row=catalog.find(row=>row[0]===id);if(!row)throw Error('지원하지 않는 지침입니다.');
    const d={group:row[2],ref:id,edits:{},initial:{},before:{},draft:{selected:id,text:''}};load(d,id);
    // ref: one kept draft per guide, so a draft kept by Esc/outside click for one guide never stands in for another.
    const s=WUI.openSheet('promptGuide',d);
    // openSheet takes this fresh draft only when the kept one was untouched; this guide's fresh base comes along with it.
    if(s.draft===d.draft&&s.edits!==d.edits){s.edits[id]=d.edits[id];s.initial[id]=d.initial[id];s.before[id]=d.before[id];}
    return s;
  }
  function select(d,id){d.edits[d.draft.selected]=d.draft.text;load(d,id);}
  function defaults(id){const d=WUI.ui.dlg(id);if(!d||d.busy)return;d.draft.text=GUIDE_DEFAULTS[d.draft.selected];d.edits[d.draft.selected]=d.draft.text;notify('기본값을 불러왔습니다. 저장을 누르면 적용됩니다.','info');}
  function save(d){
    d.edits[d.draft.selected]=d.draft.text;
    const changes=Object.entries(d.edits).filter(([id,text])=>text!==d.initial[id]||(text===GUIDE_DEFAULTS[id]&&d.before[id]!==null));
    for(const [id,text] of changes){
      if(typeof text!=='string'||!text.trim())throw Error('빈 지침은 저장할 수 없습니다. 기본값을 불러오세요.');
      if(text.length>120000)throw Error('지침 하나는 120,000자 이내로 입력해 주세요.');
      if(raw(id)!==d.before[id])throw Error('다른 창에서 지침이 변경되었습니다. 편집 내용을 복사한 뒤 창을 다시 열어 주세요.');
    }
    const written=[];
    try{for(const [id,text] of changes){
      const key=API_GUIDE_STORAGE_KEYS[id],next=text===GUIDE_DEFAULTS[id]?null:JSON.stringify({format:'wish-rp-guide',baseVersion:API_GUIDE_BASE_VERSION,text});
      written.push([id,next]);if(next===null)localStorage.removeItem(key);else localStorage.setItem(key,next);
      if(raw(id)!==next)throw Error('지침 저장을 확인하지 못했습니다.');
    }}catch(error){
      let failed=false;for(const [id,next] of written.reverse())try{if(raw(id)===next){if(d.before[id]===null)localStorage.removeItem(API_GUIDE_STORAGE_KEYS[id]);else localStorage.setItem(API_GUIDE_STORAGE_KEYS[id],d.before[id]);}}catch(_){failed=true;}
      throw WLOG.tag(Error('지침을 저장하지 못했습니다. 편집 내용은 창에 남아 있습니다. '+(failed?'일부 저장값을 확인해 주세요. ':'')+error.message),error?.name==='QuotaExceededError'?'STORE_LS_QUOTA':'');
    }
    if(changes.length){allFitRankCache.clear();recallScoreStoreClear();wishContextBuildCache=null;/* PRIVATE_DIRTY */}
    notify(changes.length?'지침을 저장했습니다. 다음 요청·TXT 내보내기부터 적용됩니다.':'변경된 지침이 없습니다.','success');
    return true;
  }
  // Read the two small override records only; no timer or RP traversal is added.
  function selectorStamp(){try{return JSON.stringify([raw('apiRecall'),raw('apiIndex')]);}catch(_){return 'storage-unavailable';}}
  // A text saved against an older default: shown in the editor only. Each guide is compared with the version in which its own
  // default last changed (a saved text without a version counts as oldest); apiIndex and apiLoreConversion
  // have kept their defaults since saved texts carry a version.
  const DEFAULT_CHANGED={apiMemory:'2.0.14',apiTimeline:'1.13.0',apiObserve:'2.0.13',apiLoreBundle:'1.9.0',apiThreads:'2.0.3',apiRelationships:'2.0.13',apiDelta:'1.8.0',apiRecall:'1.9.0',apiBundleMemory:'2.0.14',apiBundlePeople:'2.0.3',externalAll:'2.0.13',externalMemory:'2.0.13',externalPeople:'2.0.13',externalRelationships:'2.0.13',loreExternal:'2.0.4',externalSecondary:'2.0.13',apiSpeech:'2.0.3',apiDate:'1.9.0',
    apiCommon:'2.0.13',manualRelay:'1.7.0',currentState:'1.7.0',logSummary:'1.7.0',loreAuto:'1.7.0'};
  const versionParts=v=>{const m=String(v||'').match(/^(\d+)\.(\d+)\.(\d+)$/);return m?m.slice(1).map(Number):[0,0,0];};
  function stale(id){
    const r=readGuideRecord(id),since=DEFAULT_CHANGED[id];if(!r||!since)return false;
    const a=versionParts(r.baseVersion),b=versionParts(since),at=a.findIndex((n,i)=>n!==b[i]);return at>=0&&a[at]<b[at];
  }
  return {catalog,open,select,defaults,save,selectorStamp,stale};
})();

